#include "dual_state_autograd.cuh"
#include <random>
#include <cstdio>
int main(){try{using namespace tao::dual;Config c;c.layers=2;c.d=3;c.s=2;c.m=2;c.e=4;c.vocab=261;CpuModel cpu(c);std::mt19937 rng(9381);std::normal_distribution<float>d(0,.12f);for(auto&kv:cpu.w)for(auto&z:kv.second)z=kv.first.find("norm")!=std::string::npos?1.f:d(rng);TrainGraph graph(cpu);auto state=cpu.initial();Node out;double parity=0;for(unsigned t:{17u,19u,23u}){out=graph.step(t);auto a=out->value.host(),b=cpu.step(t,state);for(size_t i=0;i<a.size();++i)parity=std::max(parity,double(std::abs(a[i]-b[i])));}if(parity>2e-5)throw std::runtime_error("forward");Vec seed(261);seed[17]=.7f;seed[31]=-.2f;check(cudaMemcpy(out->grad.p,seed.data(),seed.size()*4,cudaMemcpyHostToDevice));graph.tape.backward();auto loss=[&](){auto st=cpu.initial();Vec y;for(unsigned t:{17u,19u,23u})y=cpu.step(t,st);return double(y[17])*.7-double(y[31])*.2;};double worst=0;size_t checks=0;for(auto&kv:cpu.w){auto g=graph.w.at(kv.first)->grad.host();for(size_t j=0;j<kv.second.size();++j){float old=kv.second[j],eps=.002f;kv.second[j]=old+eps;double a=loss(),hi=kv.second[j];kv.second[j]=old-eps;double b=loss(),lo=kv.second[j];kv.second[j]=old;double num=(a-b)/(hi-lo),err=std::abs(num-g[j]);if(!std::isfinite(err)||err>.006*(1+std::abs(num))){printf("BAD %s %zu numeric=%.8g cuda=%.8g\n",kv.first.c_str(),j,num,g[j]);throw std::runtime_error("gradient");}worst=std::max(worst,err);++checks;}}printf("PASS graph params=%zu tokens=3 layers=2 forward_max=%.9g grad_max=%.9g\n",checks,parity,worst);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
